mapper.select:
select DATA_STATUS as dataStatus, MOCK_DATE as mockDate, GENERATE_TIME as generateTime, PRD_DESIGN_ID as prdDesignId, PRD_SCALE as prdScale, PRD_PERIOD as prdPeriod, RATE_MAX as rateMax, RATE_MIX as rateMix, SEQ_NO seqNo, REQUIREMENT_ID requirementId, null as workflowId FROM MOCK_RESULT_INFO M where 1=1
AND (M.PRD_DESIGN_ID in
null) or M.PRD_DESIGN_ID in (
#{item}
)
and M.MOCK_DATE = STR_TO_DATE(#{mockDate}, '%Y-%m-%d')
and M.DATA_STATUS = #{dataStatus}
UNION All select WORKFLOW_STATUS as dataStatus, MOCK_DATE as mockDate, GENERATE_TIME as generateTime, PRD_DESIGN_ID as prdDesignId, PRD_SCALE as prdScale, PRD_PERIOD as prdPeriod, RATE_MAX as rateMax, RATE_MIX as rateMix, SEQ_NO seqNo, REQUIREMENT_ID requirementId, WORKFLOW_ID as workflowId FROM WFL_MOCK_RESULT_INFO WMRI where 1=1
AND (WMRI.PRD_DESIGN_ID in
null) or WMRI.PRD_DESIGN_ID in (
#{item}
)
and WMRI.MOCK_DATE = STR_TO_DATE(#{mockDate}, '%Y-%m-%d')
and WMRI.WORKFLOW_STATUS = #{dataStatus}
